/// Event Type. See https://github.com/the-blue-alliance/the-blue-alliance/blob/main/src/backend/common/consts/event_type.py for definitions.
///
/// Unknown numeric values are retained to remain forward-compatible.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum EventType {
	/// Integer: 0
	Regional,
	/// Integer: 1
	District,
	/// Integer: 2
	DistrictCmp,
	/// Integer: 3
	CmpDivision,
	/// Integer: 4
	CmpFinals,
	/// Integer: 5
	DistrictCmpDivision,
	/// Integer: 6
	Foc,
	/// Integer: 7
	Remote,
	/// Integer: 99
	Offseason,
	/// Integer: 100
	Preseason,
	/// Integer: -1
	Unlabled,
	/// A value introduced by a newer API version.
	Unknown(i64),
}

impl EventType {
	pub const fn value(self) -> i64 {
		match self {
			Self::Regional => 0,
			Self::District => 1,
			Self::DistrictCmp => 2,
			Self::CmpDivision => 3,
			Self::CmpFinals => 4,
			Self::DistrictCmpDivision => 5,
			Self::Foc => 6,
			Self::Remote => 7,
			Self::Offseason => 99,
			Self::Preseason => 100,
			Self::Unlabled => -1,
			Self::Unknown(value) => value,
		}
	}
}

impl From<i64> for EventType {
	fn from(value: i64) -> Self {
		match value {
			0 => Self::Regional,
			1 => Self::District,
			2 => Self::DistrictCmp,
			3 => Self::CmpDivision,
			4 => Self::CmpFinals,
			5 => Self::DistrictCmpDivision,
			6 => Self::Foc,
			7 => Self::Remote,
			99 => Self::Offseason,
			100 => Self::Preseason,
			-1 => Self::Unlabled,
			value => Self::Unknown(value),
		}
	}
}

impl From<EventType> for i64 {
	fn from(value: EventType) -> Self {
		value.value()
	}
}

impl serde::Serialize for EventType {
	fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
	where
		S: serde::Serializer,
	{
		serializer.serialize_i64((*self).value())
	}
}

impl<'de> serde::Deserialize<'de> for EventType {
	fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
	where
		D: serde::Deserializer<'de>,
	{
		<i64 as serde::Deserialize>::deserialize(deserializer).map(Self::from)
	}
}

