/// Playoff bracket format. See https://github.com/the-blue-alliance/the-blue-alliance/blob/main/src/backend/common/consts/playoff_type.py for definitions.
///
/// Unknown numeric values are retained to remain forward-compatible.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum PlayoffType {
	/// Integer: 1
	Bracket16Team,
	/// Integer: 0
	Bracket8Team,
	/// Integer: 2
	Bracket4Team,
	/// Integer: 9
	Bracket2Team,
	/// Integer: 3
	AvgScore8Team,
	/// Integer: 4
	RoundRobin6Team,
	/// Integer: 5
	LegacyDoubleElim8Team,
	/// Integer: 10
	DoubleElim8Team,
	/// Integer: 11
	DoubleElim4Team,
	/// Integer: 6
	Bo5Finals,
	/// Integer: 7
	Bo3Finals,
	/// Integer: 8
	Custom,
	/// A value introduced by a newer API version.
	Unknown(i64),
}

impl PlayoffType {
	pub const fn value(self) -> i64 {
		match self {
			Self::Bracket16Team => 1,
			Self::Bracket8Team => 0,
			Self::Bracket4Team => 2,
			Self::Bracket2Team => 9,
			Self::AvgScore8Team => 3,
			Self::RoundRobin6Team => 4,
			Self::LegacyDoubleElim8Team => 5,
			Self::DoubleElim8Team => 10,
			Self::DoubleElim4Team => 11,
			Self::Bo5Finals => 6,
			Self::Bo3Finals => 7,
			Self::Custom => 8,
			Self::Unknown(value) => value,
		}
	}
}

impl From<i64> for PlayoffType {
	fn from(value: i64) -> Self {
		match value {
			1 => Self::Bracket16Team,
			0 => Self::Bracket8Team,
			2 => Self::Bracket4Team,
			9 => Self::Bracket2Team,
			3 => Self::AvgScore8Team,
			4 => Self::RoundRobin6Team,
			5 => Self::LegacyDoubleElim8Team,
			10 => Self::DoubleElim8Team,
			11 => Self::DoubleElim4Team,
			6 => Self::Bo5Finals,
			7 => Self::Bo3Finals,
			8 => Self::Custom,
			value => Self::Unknown(value),
		}
	}
}

impl From<PlayoffType> for i64 {
	fn from(value: PlayoffType) -> Self {
		value.value()
	}
}

impl serde::Serialize for PlayoffType {
	fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
	where
		S: serde::Serializer,
	{
		serializer.serialize_i64((*self).value())
	}
}

impl<'de> serde::Deserialize<'de> for PlayoffType {
	fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
	where
		D: serde::Deserializer<'de>,
	{
		<i64 as serde::Deserialize>::deserialize(deserializer).map(Self::from)
	}
}

